(32861, 'Leviticus 8:20', 'Leviticus', 8, 20, 'هغه پسه ټوټې ټوټې کړ او هغه یې د سر او پاتې ټوټو او وازګې سره وسوځول.', 'هغه پسه توتې توتې کر او هغه یې د سر او پاتې توتو او وازګې سره وسوجول.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Leviticus_8_20.mp3', 'https://drive.google.com/uc?id=1r3Ig5TE_qlXsf6DlkgdbMEWFzRDlhl_n&export=download', 1761237837, 1761237837),
(32862, 'Leviticus 8:21', 'Leviticus', 8, 21, 'څنګه چې څښتن موسی ته امر کړی ؤ، هغه د نس دنننۍ برخې او پښې ووینځلې او ټول پسه یې د قربانۍ په ځای باندې وسوځاوه. دا یوه سوځېدونکې نذرانه وه چې بوی یې په څښتن باندې ښه ولګېده.', 'چنګه چې چشتن موسی ته امر کری و، هغه د نس دنننی برخې او پشې ووینجلې او تول پسه یې د قربانی په جای باندې وسوجاوه. دا یوه سوجېدونکې نذرانه وه چې بوی یې په چشتن باندې شه ولګېده.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Leviticus_8_21.mp3', 'https://drive.google.com/file/d/1n9uJZulpA6k3KDVUt1u__4VFm6UPzc12/preview', 1761237837, 1761237837),
(32863, 'Leviticus 8:22', 'Leviticus', 8, 22, 'بیا موسی بل پسه راوست. دا پسه د کاهنانو د ټاکنې دپاره ؤ. هارون او د هغه زامنو خپل لاسونه د هغه په سر باندې کېښودل.', 'بیا موسی بل پسه راوست. دا پسه د کاهنانو د تاکنې دپاره و. هارون او د هغه زامنو خپل لاسونه د هغه په سر باندې کېشودل.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Leviticus_8_22.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(32864, 'Leviticus 8:23', 'Leviticus', 8, 23, 'موسی پسه حلال کړ او د هغه لږه وینه یې واخیستله او د هارون د ښي غوږ په نرمۍ، د ښي لاس په غټې ګوتې او د ښي پښې په غټه ګوته یې وسولوله.', 'موسی پسه حلال کر او د هغه لزه وینه یې واخیستله او د هارون د شی غوز په نرمی، د شی لاس په غتې ګوتې او د شی پشې په غته ګوته یې وسولوله.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Leviticus_8_23.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(32865, 'Leviticus 8:24', 'Leviticus', 8, 24, 'بیا یې د هارون زامن مخکې راوستل او د هغوی د ښي غوږونو په نرمیو، د ښي لاسونو په غټو ګوتو او د ښي پښو په غټو ګوتو یې لږه وینه وسولوله او پاتې وینه یې د قربانۍ د ځای په څلورو خواو باندې وشیندله.', 'بیا یې د هارون زامن مخکې راوستل او د هغوی د شی غوزونو په نرمیو، د شی لاسونو په غتو ګوتو او د شی پشو په غتو ګوتو یې لزه وینه وسولوله او پاتې وینه یې د قربانی د جای په چلورو خواو باندې وشیندله.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Leviticus_8_24.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(32866, 'Leviticus 8:25', 'Leviticus', 8, 25, 'هغه وازګه، لم، هغه ټوله وازګه چې په کولمو باندې پرته وي، د اینې ډېره ښه برخه، پښتورګي د وازګې سره چې ورباندې پرته وي او ښي ورون واخیستل.', 'هغه وازګه، لم، هغه توله وازګه چې په کولمو باندې پرته وی، د اینې دېره شه برخه، پشتورګی د وازګې سره چې ورباندې پرته وی او شی ورون واخیستل.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Leviticus_8_25.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(32867, 'Leviticus 8:26', 'Leviticus', 8, 26, 'بیا هغه د فطیرې ډوډۍ د ټوکرۍ څخه چې څښتن ته وقف شوې وه یوه ساده ډوډۍ، یوه غوړه ډوډۍ او یوه نرۍ ډوډۍ راواخیستله او د وازګې او ښي ورون دپاسه یې کېښودله.', 'بیا هغه د فطیرې دودی د توکری چخه چې چشتن ته وقف شوې وه یوه ساده دودی، یوه غوره دودی او یوه نری دودی راواخیستله او د وازګې او شی ورون دپاسه یې کېشودله.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Leviticus_8_26.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(32868, 'Leviticus 8:27', 'Leviticus', 8, 27, 'موسی هغه ټول د هارون او د هغه د زامنو په لاسونو کې کېښودل او دوی هغه پورته ونیول، ترڅو دا وښایي چې هغه څښتن ته وقف شوي دي.', 'موسی هغه تول د هارون او د هغه د زامنو په لاسونو کې کېشودل او دوی هغه پورته ونیول، ترچو دا وشایی چې هغه چشتن ته وقف شوی دی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Leviticus_8_27.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237837, 1761237837),
(32869, 'Leviticus 8:28', 'Leviticus', 8, 28, 'بیا موسی دا شیان د هغوی څخه بېرته واخیستل او هغه یې د ټاکنې د نذرانې په توګه د سوځېدونکې نذرانې سره د قربانۍ په ځای باندې وسوځول. د داسې نذرانې بوی په څښتن باندې ښه لګېده.', 'بیا موسی دا شیان د هغوی چخه بېرته واخیستل او هغه یې د تاکنې د نذرانې په توګه د سوجېدونکې نذرانې سره د قربانی په جای باندې وسوجول. د داسې نذرانې بوی په چشتن باندې شه لګېده.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Leviticus_8_28.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(32870, 'Leviticus 8:29', 'Leviticus', 8, 29, 'بیا موسی د پسه سینه راواخیستله او د څښتن په حضور کې یې پورته ونیوله، ترڅو دا وښایي چې هغه څښتن ته وقف شوې ده. دا د ټاکنې په پسه کې د موسی برخه وه. موسی دا ټول کارونه د څښتن د حکم سره سم سرته ورسول.', 'بیا موسی د پسه سینه راواخیستله او د چشتن په حضور کې یې پورته ونیوله، ترچو دا وشایی چې هغه چشتن ته وقف شوې ده. دا د تاکنې په پسه کې د موسی برخه وه. موسی دا تول کارونه د چشتن د حکم سره سم سرته ورسول.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Leviticus_8_29.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(32871, 'Leviticus 8:30', 'Leviticus', 8, 30, 'موسی لږ د مسح کولو تېل او لږه وینه چې د قربانۍ په ځای باندې پرته وه واخیستل او په هارون، د هغه په زامنو او د هغو په کالیو باندې یې وشیندل. په دې ډول یې هغوی او د هغوی کالي څښتن ته وقف کړل.', 'موسی لز د مسح کولو تېل او لزه وینه چې د قربانی په جای باندې پرته وه واخیستل او په هارون، د هغه په زامنو او د هغو په کالیو باندې یې وشیندل. په دې دول یې هغوی او د هغوی کالی چشتن ته وقف کرل.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Leviticus_8_30.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(32872, 'Leviticus 8:31', 'Leviticus', 8, 31, 'موسی هارون او د هغه زامنو ته وویل: «لکه څنګه چې څښتن حکم کړی دی دا غوښه د سپېڅلې خېمې د دروازې په خوله کې پخه کړئ او هلته یې د هغې ډوډۍ سره چې د ټاکنې د نذرانې په ټوکرۍ کې ده، وخورئ.', 'موسی هارون او د هغه زامنو ته وویل: «لکه چنګه چې چشتن حکم کری دی دا غوشه د سپېچلې خېمې د دروازې په خوله کې پخه کری او هلته یې د هغې دودی سره چې د تاکنې د نذرانې په توکری کې ده، وخوری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Leviticus_8_31.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(32873, 'Leviticus 8:32', 'Leviticus', 8, 32, 'کومه غوښه یا ډوډۍ چې پاتې شي، نو هغه وسوځوئ.', 'کومه غوشه یا دودی چې پاتې شی، نو هغه وسوجوی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Leviticus_8_32.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(32874, 'Leviticus 8:33', 'Leviticus', 8, 33, 'تاسو به اووه ورځې د خېمې د دروازې د خولې څخه نه ځئ، ترڅو پورې چې ستاسو د ټاکنې مراسم پوره شوي نه وي.', 'تاسو به اووه ورجې د خېمې د دروازې د خولې چخه نه جی، ترچو پورې چې ستاسو د تاکنې مراسم پوره شوی نه وی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Leviticus_8_33.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(32875, 'Leviticus 8:34', 'Leviticus', 8, 34, 'مونږ چې نن کوم کار وکړ، څښتن د هغه د کولو حکم مونږ ته کړی ؤ، د دې په خاطر چې ستاسو د ګناه دپاره کفاره ادا کړو.', 'مونز چې نن کوم کار وکر، چشتن د هغه د کولو حکم مونز ته کری و، د دې په خاطر چې ستاسو د ګناه دپاره کفاره ادا کرو.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Leviticus_8_34.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(32876, 'Leviticus 8:35', 'Leviticus', 8, 35, 'تاسو باید د سپېڅلې خېمې د دروازې په خوله کې اووه شپې او اووه ورځې پاتې شئ او هغه کار به کوئ چې څښتن یې امر کړی دی. که چېرې داسې ونه کړئ نو مړه به شئ، ځکه چې څښتن په ما باندې داسې امر کړی دی.»', 'تاسو باید د سپېچلې خېمې د دروازې په خوله کې اووه شپې او اووه ورجې پاتې شی او هغه کار به کوی چې چشتن یې امر کری دی. که چېرې داسې ونه کری نو مره به شی، جکه چې چشتن په ما باندې داسې امر کری دی.»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Leviticus_8_35.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237837, 1761237837),
(32877, 'Leviticus 8:36', 'Leviticus', 8, 36, 'نو هارون او د هغه زامنو ټول کارونه د څښتن د هغه حکم له مخې وکړل چې د موسی په وسیله یې کړی ؤ.', 'نو هارون او د هغه زامنو تول کارونه د چشتن د هغه حکم له مخې وکرل چې د موسی په وسیله یې کری و.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Leviticus_8_36.mp3', 'https://drive.google.com/uc?id=13eil4SOoNQQSXZBOhEsegwZ3bF97K2v8&export=download', 1761237837, 1761237837),
(32878, 'Proverbs 3:1', 'Proverbs', 3, 1, 'ای زما زویه! زما تعلیم مه هېروه او زما حکمونه په خپل زړه کې ټینګ وساته', 'ای زما زویه! زما تعلیم مه هېروه او زما حکمونه په خپل زره کې تینګ وساته', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs003_verse_001.mp3', 'https://drive.google.com/file/d/1Qhqu8s0Fl3vQxt5_nuApDLP4z_Cu3Wgb/preview', 1761237837, 1761237837),
(32879, 'Proverbs 3:2', 'Proverbs', 3, 2, 'ځکه دا به ستا د عمر ورځې او کلونه ډېر کړي او سوله او سلامتي به در په برخه کړي.', 'جکه دا به ستا د عمر ورجې او کلونه دېر کری او سوله او سلامتی به در په برخه کری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs003_verse_002.mp3', 'https://drive.google.com/file/d/1DtW6U5oDhqIfJEasqhNL3ctWhWkPCI44/preview', 1761237837, 1761237837),
(32880, 'Proverbs 3:3', 'Proverbs', 3, 3, 'مینه او وفا د خپل ځانه مه لېرې کوه هغه د تل دپاره د خپلې غاړې هار کړه او د خپل زړه په تخته یې ولیکه.', 'مینه او وفا د خپل جانه مه لېرې کوه هغه د تل دپاره د خپلې غارې هار کره او د خپل زره په تخته یې ولیکه.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs003_verse_003.mp3', 'https://drive.google.com/file/d/1p745M24odFF7KwPSwwhIuwfI_Xo8r32c/preview', 1761237837, 1761237837),
(32881, 'Proverbs 3:4', 'Proverbs', 3, 4, 'نو بیا به ته د خدای او انسان په نظر کې نېک وګڼل شې او د یو هوښیار انسان په توګه وپېژندل شې.', 'نو بیا به ته د خدای او انسان په نظر کې نېک وګنل شې او د یو هوشیار انسان په توګه وپېژندل شې.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs003_verse_004.mp3', 'https://drive.google.com/file/d/1F8xf2XtpTmWugPnYS_Ph2c1urFixhZUe/preview', 1761237837, 1761237837),
(32882, 'Proverbs 3:5', 'Proverbs', 3, 5, 'په خپل ټول زړه په څښتن توکل کوه او په خپل عقل او پوهه تکیه مه کوه.', 'په خپل تول زره په چشتن توکل کوه او په خپل عقل او پوهه تکیه مه کوه.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs003_verse_005.mp3', 'https://drive.google.com/file/d/1eOxf2aB5PNVmbAK68-XFpF7nvd1xx_xC/preview', 1761237837, 1761237837),
(32883, 'Proverbs 3:6', 'Proverbs', 3, 6, 'په هر کار کې د هغه د حضور غوښتنه کوه نو هغه به ستا لارې هوارې کړي.', 'په هر کار کې د هغه د حضور غوشتنه کوه نو هغه به ستا لارې هوارې کری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs003_verse_006.mp3', 'https://drive.google.com/file/d/1bFhTjZDXTVTnDlCisVmYRc0pLbio_rjh/preview', 1761237837, 1761237837),
